// GENERATED by scripts/sync-shared.mjs from src/backend. Do not edit here.
import { findTemplate } from '../domain/catalog.ts';
import { stars } from './starsText.ts';
import type { Catalog, DomainEvent, FamilyState, WeeklyResult } from '../domain/types.ts';

/**
 * Push notifications for domain events (spec 14: approvals, rewards, weekly summary).
 * `url` is the route the app opens on tap, so a parent approves with at most two
 * taps: the notification, then "Godkänn" (spec 15 acceptance criteria).
 */

export type PushAudience = { kind: 'parents' } | { kind: 'child'; childId: string };

export interface PushMessage {
  audience: PushAudience;
  title: string;
  body: string;
  url: string;
}

const APP_NAME = 'JagKan!';

function childName(state: FamilyState, childId: string): string {
  return state.children.find((c) => c.id === childId)?.firstName ?? '';
}

export function messagesForEvents(state: FamilyState, events: DomainEvent[], catalog: Catalog): PushMessage[] {
  const settings = state.family.settings.notifications;
  const out: PushMessage[] = [];
  for (const event of events) {
    if (event.type === 'completion_requested' && settings.approvals) {
      const challenge = state.challenges.find((c) => c.id === event.challengeId);
      const title = challenge ? (findTemplate(catalog, challenge.templateId)?.titleParent ?? challenge.customTitle ?? '') : '';
      out.push({
        audience: { kind: 'parents' },
        title: `${childName(state, event.childId)} säger: Jag klarade det!`,
        body: title,
        url: `/parent/approve/${event.challengeId}`,
      });
    } else if (event.type === 'reward_requested' && settings.approvals) {
      const request = state.rewardRequests.find((r) => r.id === event.requestId);
      const reward = state.rewards.find((r) => r.id === request?.rewardId);
      out.push({
        audience: { kind: 'parents' },
        title: APP_NAME,
        body: `${childName(state, event.childId)} vill ha: ${reward?.title ?? ''}`,
        url: '/parent/rewards',
      });
    } else if (event.type === 'challenge_completed') {
      out.push({ audience: { kind: 'child', childId: event.childId }, title: APP_NAME, body: 'En vuxen har godkänt! ⭐', url: '/child' });
    } else if (event.type === 'reward_resolved' && event.confirmed) {
      const request = state.rewardRequests.find((r) => r.id === event.requestId);
      const reward = state.rewards.find((r) => r.id === request?.rewardId);
      out.push({
        audience: { kind: 'child', childId: event.childId },
        title: APP_NAME,
        body: `Belöningen är din: ${reward?.title ?? ''}!`,
        url: '/child/shop',
      });
    }
  }
  return out;
}

/** Sunday-evening summary to the parents (spec 14.2 weekly-rollup). */
export function weeklySummaryMessage(state: FamilyState, result: WeeklyResult): PushMessage | null {
  if (!state.family.settings.notifications.weeklySummary || result.results.length === 0) return null;
  const parts = result.results.map((r) => `${childName(state, r.childId)} ${stars(r.stars)}`);
  const winner = result.duel ? result.results.find((r) => r.isWinner) : undefined;
  const lead = winner ? `${childName(state, winner.childId)} vann veckan! 🏆 ` : '';
  return { audience: { kind: 'parents' }, title: 'Veckan i JagKan!', body: `${lead}${parts.join(', ')}`, url: '/parent' };
}
